import { execFile } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { promisify } from "node:util";
import { sessionExperimentsPath, watchAgentSessionExperiments, } from "./commands/watchRunningExperiments.js";
import { parseArgs } from "./parseArgs.js";
const run = promisify(execFile);
const CODEX_IDLE_STOP_MS = 24 * 60 * 60_000;
const ROLLOUT_TAIL_BYTES = 256 * 1024;
const PROCESS_CHECK_MS = 30_000;
const TURN_STARTED = '"type":"task_started"';
const TURN_ENDED = '"type":"task_complete"';
const TURN_ABORTED = '"type":"turn_aborted"';
function experimentLabel(experiment) {
    return experiment.name ?? `Experiment ${experiment.id.slice(0, 8)}`;
}
function progressLabel(counts) {
    return counts.total === null
        ? `${counts.finished} replayed`
        : `${counts.finished}/${counts.total} replayed`;
}
function stallText(experiment) {
    return [
        `Bitfab experiment ${experimentLabel(experiment)} (${experiment.id}) has replayed nothing new for 10 minutes and is still marked running (${progressLabel(experiment)}), ${experiment.url}`,
        "Check whether its replay process is still running and read that replay's output for an error; for a cloud replay, run bitfab-replay --cloud-status <execution UUID>. If the process is gone, get_replay_status says whether it can be resumed: rerun the same replay command with --resume <experiment id>.",
    ].join("\n");
}
function finishedOutcome(experiment) {
    if (experiment.status !== "completed") {
        return experiment.status;
    }
    const everyReplayErrored = typeof experiment.errored === "number" &&
        experiment.errored > 0 &&
        experiment.errored === experiment.finished;
    return everyReplayErrored ? "errored" : "complete";
}
function finishedCounts(experiment) {
    if (experiment.status === "failed") {
        return "";
    }
    const errored = typeof experiment.errored === "number" && experiment.errored > 0
        ? `, ${experiment.errored} errored`
        : "";
    return `, ${progressLabel({ finished: experiment.finished, total: experiment.total })}${errored}`;
}
function finishText(experiment) {
    return [
        `Bitfab experiment ${experimentLabel(experiment)} (${experiment.id}) finished: ${finishedOutcome(experiment)}${finishedCounts(experiment)}, ${experiment.url}`,
        "Read its results with get_experiment and list_experiment_traces, then report what improved and regressed against the baseline.",
    ].join("\n");
}
export function pickCodexWakes(snapshot, handled, turnRunning) {
    const wakes = [];
    for (const experiment of snapshot.running) {
        const key = `stall:${experiment.id}`;
        if (experiment.stalled && !handled.has(key)) {
            handled.add(key);
            wakes.push({ experimentId: experiment.id, text: stallText(experiment) });
        }
    }
    for (const experiment of snapshot.finished) {
        const key = `finish:${experiment.id}`;
        if (handled.has(key)) {
            continue;
        }
        handled.add(key);
        if (experiment.announce && !turnRunning) {
            wakes.push({ experimentId: experiment.id, text: finishText(experiment) });
        }
    }
    return wakes;
}
export function codexTurnRunning(rolloutText) {
    const started = rolloutText.lastIndexOf(TURN_STARTED);
    const ended = Math.max(rolloutText.lastIndexOf(TURN_ENDED), rolloutText.lastIndexOf(TURN_ABORTED));
    return started > ended;
}
function hasTurnMarker(rolloutText) {
    return [TURN_STARTED, TURN_ENDED, TURN_ABORTED].some((marker) => rolloutText.includes(marker));
}
export function readRolloutForTurnCheck(file) {
    const handle = fs.openSync(file, "r");
    try {
        const size = fs.fstatSync(handle).size;
        const length = Math.min(size, ROLLOUT_TAIL_BYTES);
        const buffer = Buffer.alloc(length);
        fs.readSync(handle, buffer, 0, length, size - length);
        const tail = buffer.toString("utf8");
        if (length === size || hasTurnMarker(tail)) {
            return tail;
        }
        return fs.readFileSync(file, "utf8");
    }
    finally {
        fs.closeSync(handle);
    }
}
function findRollout(directory, threadId) {
    let entries;
    try {
        entries = fs.readdirSync(directory, { withFileTypes: true });
    }
    catch {
        return null;
    }
    for (const entry of entries.sort((a, b) => b.name.localeCompare(a.name))) {
        const full = path.join(directory, entry.name);
        if (entry.isDirectory()) {
            const found = findRollout(full, threadId);
            if (found !== null) {
                return found;
            }
        }
        else if (entry.name.endsWith(`-${threadId}.jsonl`)) {
            return full;
        }
    }
    return null;
}
function isAlive(pid) {
    try {
        process.kill(pid, 0);
        return true;
    }
    catch (error) {
        return error.code === "EPERM";
    }
}
function claimThread(threadId) {
    const directory = sessionExperimentsPath(os.homedir(), threadId);
    if (directory === null) {
        return false;
    }
    const lockPath = path.join(directory, "codex-waker.pid");
    try {
        const holder = Number(fs.readFileSync(lockPath, "utf8").trim());
        if (holder !== process.pid && holder > 0 && isAlive(holder)) {
            return false;
        }
    }
    catch { }
    fs.mkdirSync(path.dirname(lockPath), { recursive: true });
    fs.writeFileSync(lockPath, `${process.pid}\n`);
    return true;
}
async function queueMessage(threadId, text) {
    const args = ["queue", "--thread", threadId, "--message", text];
    try {
        await run("codex", [...args, "--remote", "unix://"]);
    }
    catch {
        await run("codex", args);
    }
}
function readOptions() {
    const { flags } = parseArgs({
        positional: [],
        flags: [
            {
                name: "thread-id",
                description: "The Codex session whose experiments to follow.",
            },
            {
                name: "codex-pid",
                description: "The Codex process this exits with.",
            },
            {
                name: "rollout",
                description: "The session's log file, when the hook knows it.",
            },
        ],
        description: "Follow a Codex session's Bitfab experiments and queue a message to the session with codex queue when one stalls, or when one finishes while no turn is running. Started in the background by the session start hook. Exits when the Codex process exits, when another copy already follows the session, or after a day with nothing running and nothing written to the session log.",
    });
    const threadId = flags["thread-id"];
    const codexPid = Number(flags["codex-pid"]);
    const rollout = flags.rollout;
    if (typeof threadId !== "string" ||
        threadId.length === 0 ||
        !(codexPid > 0)) {
        return null;
    }
    return {
        threadId,
        codexPid,
        rolloutPath: typeof rollout === "string" && rollout ? rollout : null,
    };
}
export async function runCodexExperimentWaker(platform, pluginVersion) {
    const options = readOptions();
    if (options === null || !claimThread(options.threadId)) {
        return;
    }
    const sessionsRoot = path.join(process.env.CODEX_HOME ?? path.join(os.homedir(), ".codex"), "sessions");
    let rolloutPath = options.rolloutPath;
    const rollout = () => {
        rolloutPath ??= findRollout(sessionsRoot, options.threadId);
        return rolloutPath;
    };
    const turnRunning = () => {
        const file = rollout();
        try {
            return file !== null && codexTurnRunning(readRolloutForTurnCheck(file));
        }
        catch {
            return false;
        }
    };
    const sessionIdle = () => {
        const file = rollout();
        try {
            return (file !== null &&
                Date.now() - fs.statSync(file).mtimeMs > CODEX_IDLE_STOP_MS);
        }
        catch {
            return false;
        }
    };
    const handled = new Set();
    let running = 0;
    let stopped = false;
    const checkProcess = setInterval(() => {
        if (!isAlive(options.codexPid)) {
            process.exit(0);
        }
    }, PROCESS_CHECK_MS);
    checkProcess.unref();
    await watchAgentSessionExperiments(platform, pluginVersion, options.threadId, {
        emit: (snapshot) => {
            running = snapshot.running.length;
            for (const wake of pickCodexWakes(snapshot, handled, turnRunning())) {
                void queueMessage(options.threadId, wake.text).catch(() => undefined);
            }
        },
        shouldStop: () => {
            stopped ||=
                !isAlive(options.codexPid) || (running === 0 && sessionIdle());
            return stopped;
        },
    });
}
